import type { DroppedFile } from './lib/parse/ingest.ts'

// demo.ts — the synthetic export lives in fixtures/ (generated by
// scripts/make-fixtures.mjs). Vite inlines each file as a string so the demo
// works in the single-file build with zero network.

const raw = import.meta.glob('../fixtures/**/*', { query: '?raw', eager: true }) as Record<string, string>

export const DEMO_FILES: DroppedFile[] = Object.entries(raw)
  .map(([path, mod]) => ({
    path: path.replace(/^\.\.\/fixtures\//, '').replace(/^@fs/, ''),
    text: typeof mod === 'string' ? mod : (mod as unknown as { default: string }).default,
  }))
  .filter((f) => f.text && !f.path.endsWith('.db'))
